alter table public.profiles add column if not exists email text not null default '';
alter table public.profiles add column if not exists phone text not null default '';
alter table public.hospitals add column if not exists source_url text not null default '';
alter table public.hospitals add column if not exists source_notes text not null default '';
alter table public.hospitals add column if not exists source_verification text not null default '';
alter table public.hospitals add column if not exists ownership text not null default 'Not publicly verified';
alter table public.hospitals add column if not exists specialties text[] not null default '{}';
alter table public.hospitals add column if not exists reported_doctor_count text not null default 'Not publicly verified';
alter table public.hospitals add column if not exists image_source_url text not null default '';
alter table public.hospitals add column if not exists last_verified_at timestamptz;
alter table public.doctors add column if not exists source_url text not null default '';
alter table public.doctors add column if not exists is_verified boolean not null default false;
alter table public.doctors add column if not exists verification_status text not null default 'unverified';

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public
as $$
begin
 insert into public.profiles (id, full_name, email, phone)
 values (new.id, coalesce(new.raw_user_meta_data->>'full_name',''), coalesce(new.email,''), coalesce(new.raw_user_meta_data->>'phone',''))
 on conflict (id) do update set full_name=excluded.full_name, email=excluded.email, phone=excluded.phone;
 return new;
end;
$$;
create or replace function public.handle_user_profile_update()
returns trigger language plpgsql security definer set search_path = public
as $$
begin
 update public.profiles set email=coalesce(new.email,''),
   full_name=coalesce(new.raw_user_meta_data->>'full_name',full_name),
   phone=coalesce(new.raw_user_meta_data->>'phone',phone), updated_at=now()
 where id=new.id;
 return new;
end;
$$;
drop trigger if exists on_auth_user_profile_updated on auth.users;
create trigger on_auth_user_profile_updated after update of email, raw_user_meta_data on auth.users
for each row execute procedure public.handle_user_profile_update();

delete from public.doctors where lower(full_name) like '%sample%';
delete from public.hospitals where lower(name) like '%(sample)%' or lower(name) like 'carelink community hospital%';

