insert into public.hospitals (name,city,address,phone,category,description,image_url,is_verified,source_url,source_notes,source_verification,ownership,specialties,reported_doctor_count,image_source_url,last_verified_at)
select s.name,s.city,s.address,s.phone,s.category,
 concat_ws(' | ',nullif(s.departments,''),nullif(s.source_notes,'')), '',
 (s.verification ilike '%confirmed%'), s.source_url, s.source_notes, s.verification, s.ownership,
 s.specialties, s.doctor_count, '', now()
from source_rows s
where not exists (select 1 from public.hospitals h where lower(h.name)=lower(s.name) and lower(h.city)=lower(s.city));

-- Named clinician records are inserted only when the source document explicitly lists names.
-- Specialty is deliberately marked unspecified unless the source provides a doctor-specific specialty.
